pub(crate) async fn get_host() -> Result<Host> {
    let env = crate::store::Environment::detect()?;
    if env.needs_mount_namespace() {
        crate::cli::prepare_for_write()?;
    }

    let Some(storage) = BootedStorage::new(env, crate::store::EspAccess::ReadOnly).await? else {
        // If we're not booted, then return a default.
        return Ok(Host::default());
    };

    let mut host = match storage.kind() {
        Ok(kind) => match kind {
            BootedStorageKind::Ostree(booted_ostree) => {
                let (_deployments, host) = get_status(&booted_ostree)?;
                host
            }
            BootedStorageKind::Composefs(booted_cfs) => {
                crate::bootc_composefs::status::get_composefs_status(&storage, &booted_cfs).await?
            }
        },
        Err(_) => {
            // If determining storage kind fails (e.g., no booted deployment),
            // return a default host indicating the system is not deployed via bootc
            Host::default()
        }
    };

    // Surface whether the physical root is on a read-only medium (e.g. a live
    // ISO), so consumers know mutating operations are unavailable.
    host.status.read_only = storage.is_ro;

    Ok(host)
}

#[context("Ensuring mountns")]
pub(crate) fn ensure_self_unshared_mount_namespace(reexec_env: &[(&str, &str)]) -> Result<()> {
    let uid = rustix::process::getuid();
    if !uid.is_root() {
        tracing::debug!("Not root, assuming no need to unshare");
        return Ok(());
    }
    let recurse_env = "_ostree_unshared";
    let ns_pid1 = std::fs::read_link("/proc/1/ns/mnt").context("Reading /proc/1/ns/mnt")?;
    let ns_self = std::fs::read_link("/proc/self/ns/mnt").context("Reading /proc/self/ns/mnt")?;
    if ns_pid1 != ns_self {
        tracing::debug!("Already in a mount namespace");
        return Ok(());
    }
    if std::env::var_os(recurse_env).is_some() {
        let am_pid1 = rustix::process::getpid().is_init();
        if am_pid1 {
            tracing::debug!("We are pid 1");
            return Ok(());
        } else {
            anyhow::bail!("Failed to unshare mount namespace");
        }
    }
    let am_pid1 = rustix::process::getpid().is_init();
    if am_pid1 {
        tracing::debug!("We are pid 1");
        return Ok(());
    }
    bootc_utils::reexec::reexec_with_guardenv(
        recurse_env,
        &["unshare", "-m", "--propagation=slave", "--"],
        reexec_env,
    )
}

#[context("Querying root privilege")]
pub(crate) fn require_root(is_container: bool) -> Result<()> {
    ensure!(rustix::process::getuid().is_root(), "This command must be executed as the root user");
    ensure!(
        rustix::thread::capability_is_in_bounding_set(rustix::thread::CapabilitySet::SYS_ADMIN)?,
        "This command requires full root privileges (CAP_SYS_ADMIN)"
    );
    Ok(())
}

#[context("Preparing for write")]
pub(crate) fn prepare_for_write() -> Result<()> {
    if ostree_ext::container_utils::running_in_container() {
        anyhow::bail!("Detected container; this command requires a booted host system.");
    }
    crate::cli::require_root(false)?;
    ensure_self_unshared_mount_namespace(&[])?;
    if crate::lsm::selinux_enabled() && !crate::lsm::selinux_ensure_install(&[])? {
        tracing::debug!("Do not have install_t capabilities");
    }
    Ok(())
}

impl Environment {
    /// Detect the current runtime environment.
    pub(crate) fn detect() -> Result<Self> {
        if ostree_ext::container_utils::running_in_container() {
            return Ok(Self::Container);
        }

        if let Some(cmdline) = composefs_booted()? {
            return Ok(Self::ComposefsBooted(cmdline.clone()));
        }

        if ostree_booted()? {
            return Ok(Self::OstreeBooted);
        }

        Ok(Self::Other)
    }

    /// Returns true if this environment requires entering a mount namespace
    /// before loading storage (to avoid leaving /sysroot writable).
    pub(crate) fn needs_mount_namespace(&self) -> bool {
        matches!(self, Self::OstreeBooted | Self::ComposefsBooted(_))
    }
}
